def mark_existing_public_content_as_notified(apps, schema_editor):
    """Avoid a notification storm for content that predates this feature."""

    now = timezone.now()
    Posts = apps.get_model('blog', 'Posts')
    Event = apps.get_model('blog', 'Event')
    PollQuestion = apps.get_model('blog', 'PollQuestion')
    Mission = apps.get_model('blog', 'Mission')

    Posts.objects.filter(
        published=True,
        allowed=True,
    ).filter(
        Q(published_at__isnull=True) | Q(published_at__lte=now)
    ).update(publication_notified_at=now)
    Event.objects.filter(published=True).update(publication_notified_at=now)
    PollQuestion.objects.filter(
        start_date__lte=now,
        end_date__gt=now,
    ).update(activation_notified_at=now)
    Mission.objects.filter(
        active=True,
        start_date__lte=now,
        end_date__gt=now,
    ).update(availability_notified_at=now)


